const $=id=>document.getElementById(id);let draftReady=false;function resetApproval(){draftReady=false;$('approve').checked=false;$('export').disabled=true;if($('print'))$('print').disabled=true;if($('download-html'))$('download-html').disabled=true;if($('report-preview'))$('report-preview').hidden=true;if($('review'))$('review').hidden=false;if($('review-label'))$('review-label').hidden=false;}function route(){const h=location.hash.slice(1);const p=['report','receipts','project'].includes(h)?h:'home';document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==p+'-view');document.querySelectorAll('[data-view]').forEach(a=>a.classList.toggle('active',a.dataset.view===p));}window.addEventListener('hashchange',route);route();
$('sample').onclick=()=>{resetApproval();$('org').value='Fictional Community Initiative';$('period').value='12–18 October 2026';$('notes').value='Held a digital-literacy workshop with 24 participants.\nDistributed 18 learning kits at that workshop.\nHeld a separate reading session with 12 attendances. These may include repeat participants; unique beneficiary total is not established.';$('challenges').value='Learning materials arrived late. Attendance at the reading session was lower than planned.';$('next').value='Confirm materials before the next workshop. Ask participants which session times work best.';location.hash='report';route();$('status').textContent='Sample notes loaded. Create a draft to continue.';};
$('draft').onclick=()=>{resetApproval();const org=$('org').value.trim(),period=$('period').value.trim(),notes=$('notes').value.trim();if(!org||!period||notes.length<30){$('status').textContent='Add your organisation, reporting period and a short description of your activities.';return;}$('review').value=`WEEKLY DONOR REPORT\n${org}\nReporting period: ${period}\n\nACTIVITIES AND REPORTED COUNTS\n${notes}\n\nCHALLENGES\n${$('challenges').value.trim()||'Not provided — coordinator to confirm.'}\n\nNEXT STEPS\n${$('next').value.trim()||'Not provided — coordinator to confirm.'}\n\nREVIEW NOTES\nCounts above are reproduced from supplied notes, not independently verified. Do not add activity attendance counts to infer unique beneficiaries.\n\nPrepared from the supplied notes.`;$('draft-area').hidden=false;$('empty-report').hidden=true;draftReady=true;$('status').textContent='Draft prepared. Check and edit every section before approving.';};
$('approve').onchange=()=>{const blocked=!($('approve').checked&&draftReady&&$('review').value.trim());$('export').disabled=blocked;$('print').disabled=blocked;};$('review').oninput=()=>{ $('approve').checked=false;$('export').disabled=true;$('print').disabled=true;};['org','period','notes','challenges','next'].forEach(id=>$(id).oninput=()=>{resetApproval();$('status').textContent='Your notes changed. Create a new draft before exporting.';});$('clear').onclick=()=>{['org','period','notes','challenges','next','review'].forEach(id=>$(id).value='');resetApproval();$('draft-area').hidden=true;$('empty-report').hidden=false;$('ai-consent').checked=false;$('status').textContent='Inputs cleared.';};$('export').onclick=()=>{if(!draftReady||!$('approve').checked||!$('review').value.trim())return;const u=URL.createObjectURL(new Blob([$('review').value],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='NGO-Approved-Report.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);$('status').textContent='Your approved report has been downloaded.';};
let installPrompt;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;$('install').hidden=false;});$('install').onclick=async()=>{if(!installPrompt)return;await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('install').hidden=true;};window.addEventListener('appinstalled',()=>{$('install').hidden=true;});
function connectionStatus(){$('connection').hidden=navigator.onLine;}window.addEventListener('online',connectionStatus);window.addEventListener('offline',connectionStatus);connectionStatus();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{console.info('Offline installation unavailable in this browser.');});
window.addEventListener('beforeunload',event=>{if($('notes').value.trim()||$('review').value.trim()){event.preventDefault();event.returnValue='';}});

const safeText=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function snapshot(){return Object.fromEntries(['org','period','notes','challenges','next'].map(k=>[k,$(k).value.trim()]));}
let requestSequence=0;
$('ai-draft').onclick=async()=>{if(!$('ai-consent').checked){$('status').textContent='Confirm consent before sending notes to AI.';return;}const input=snapshot();if(!input.org||!input.period||input.notes.length<30){$('status').textContent='Add your organisation, reporting period and a short description of your activities.';return;}const sequence=++requestSequence;const before=JSON.stringify(input);resetApproval();$('draft-area').hidden=true;$('empty-report').hidden=false;$('ai-draft').disabled=true;$('draft').disabled=true;$('status').textContent='Creating your report draft…';try{const r=await fetch('/api/report',{method:'POST',headers:{'Content-Type':'application/json'},body:before,signal:AbortSignal.timeout(65000)});const d=await r.json();if(sequence!==requestSequence||before!==JSON.stringify(snapshot())){$('status').textContent='Your notes changed. Create a new draft to include your updates.';return;}if(!r.ok)throw Error(d.error||'We couldn’t create the draft. Please try again.');if(!d.report||d.requires_review!==true)throw Error('We couldn’t read the draft. Please try again.');const parts=['WEEKLY DONOR REPORT',input.org,'Reporting period: '+input.period];for(const[k,title]of [['activities','ACTIVITIES'],['challenges','CHALLENGES'],['next_steps','NEXT STEPS']]){parts.push('\n'+title);parts.push(...d.report[k].map(x=>x.summary+'\nSource: “'+x.source_quote+'”'));if(!d.report[k].length)parts.push('Not provided — coordinator to confirm.');}parts.push('\nCOORDINATOR REVIEW',...d.report.warnings,'Verify each claim against your notes. Attendance across activities may include repeat participants.');$('review').value=parts.join('\n');$('draft-label').textContent='DRAFT / REVIEW REQUIRED';$('draft-area').hidden=false;$('empty-report').hidden=true;draftReady=true;$('status').textContent='Your draft is ready. Review the content and figures before approving.';}catch(e){$('status').textContent=e.name==='TimeoutError'?'This is taking longer than expected. Please try again shortly.':e.message;}finally{$('ai-draft').disabled=false;$('draft').disabled=false;}};
const clearAction=$('clear').onclick;$('clear').onclick=()=>{requestSequence++;clearAction();};const sampleAction=$('sample').onclick;$('sample').onclick=()=>{requestSequence++;sampleAction();};const localAction=$('draft').onclick;$('draft').onclick=()=>{requestSequence++;$('draft-label').textContent='DRAFT / REVIEW REQUIRED';localAction();};
function approvedReport(){return draftReady&&$('approve').checked&&$('review').value.trim();}
function showPreview(){if(!$('review').value.trim())return;$('report-preview').srcdoc=ReportLayout.render($('review').value,{approved:Boolean(approvedReport())});$('report-preview').hidden=false;$('review').hidden=true;$('review-label').hidden=true;}
$('preview').onclick=showPreview;
$('edit-report').onclick=()=>{$('report-preview').hidden=true;$('review').hidden=false;$('review-label').hidden=false;};
$('download-html').onclick=()=>{if(!approvedReport())return;const url=URL.createObjectURL(new Blob([ReportLayout.render($('review').value,{approved:true})],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='NGO-Approved-Donor-Report.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('print').onclick=()=>{if(!approvedReport())return;const w=window.open('','_blank');if(!w){$('status').textContent='Allow the report window to save a PDF.';return;}w.opener=null;w.document.write(ReportLayout.render($('review').value,{approved:true}));w.document.close();w.focus();setTimeout(()=>w.print(),300);};
const previousApproval=$('approve').onchange;$('approve').onchange=()=>{previousApproval();$('download-html').disabled=!approvedReport();if(!$('report-preview').hidden)showPreview();};
const previousEdit=$('review').oninput;$('review').oninput=()=>{previousEdit();$('download-html').disabled=true;};
